{
  "items": [
    {
      "name": "Finset.prod_le_pow_card",
      "type": " {ι : Type u_1} {N : Type u_5} [CommMonoid N] [Preorder N] [MulLeftMono N] (s : Finset ι) (f : ι → N) (n : N) (h : ∀ x ∈ s, f x ≤ n) : s.prod f ≤ n ^ s.card",
      "module": "Mathlib.Algebra.Order.BigOperators.Group.Finset"
    },
    {
      "name": "Real.harm_mean_le_geom_mean",
      "type": " {ι : Type u_1} (s : Finset ι) (hs : s.Nonempty) (w z : ι → ℝ) (hw : ∀ i ∈ s, 0 < w i) (hw' : 0 < ∑ i ∈ s, w i) (hz : ∀ i ∈ s, 0 < z i) : (∑ i ∈ s, w i) / ∑ i ∈ s, w i / z i ≤ (∏ i ∈ s, z i ^ w i) ^ (∑ i ∈ s, w i)⁻¹",
      "module": "Mathlib.Analysis.MeanInequalities"
    },
    {
      "name": "MeasureTheory.lintegral_prod_lintegral_pow_le",
      "type": " {ι : Type u_1} {A : ι → Type u_2} [(i : ι) → MeasurableSpace (A i)] (μ : (i : ι) → MeasureTheory.Measure (A i)) [DecidableEq ι] [Fintype ι] [∀ (i : ι), MeasureTheory.SigmaFinite (μ i)] {p : ℝ} (hp : (↑(Fintype.card ι)).HolderConjugate p) {f : ((a : ι) → A a) → ENNReal} (hf : Measurable f) : ∫⁻ (x : (i : ι) → A i), ∏ i, (∫⁻ (xᵢ : A i), f (Function.update x i xᵢ) ∂μ i) ^ (1 / (↑(Fintype.card ι) - 1)) ∂MeasureTheory.Measure.pi μ ≤ (∫⁻ (x : (i : ι) → A i), f x ∂MeasureTheory.Measure.pi μ) ^ p",
      "module": "Mathlib.Analysis.FunctionalSpaces.SobolevInequality"
    },
    {
      "name": "MeasureTheory.lintegral_mul_prod_lintegral_pow_le",
      "type": " {ι : Type u_1} {A : ι → Type u_2} [(i : ι) → MeasurableSpace (A i)] (μ : (i : ι) → MeasureTheory.Measure (A i)) [DecidableEq ι] [Fintype ι] [∀ (i : ι), MeasureTheory.SigmaFinite (μ i)] {p : ℝ} (hp₀ : 0 ≤ p) (hp : (↑(Fintype.card ι) - 1) * p ≤ 1) {f : ((i : ι) → A i) → ENNReal} (hf : Measurable f) : ∫⁻ (x : (i : ι) → A i), f x ^ (1 - (↑(Fintype.card ι) - 1) * p) * ∏ i, (∫⁻ (xᵢ : A i), f (Function.update x i xᵢ) ∂μ i) ^ p ∂MeasureTheory.Measure.pi μ ≤ (∫⁻ (x : (i : ι) → A i), f x ∂MeasureTheory.Measure.pi μ) ^ (1 + p)",
      "module": "Mathlib.Analysis.FunctionalSpaces.SobolevInequality"
    }
  ]
}
